const body = $input.first().json.body || $input.first().json;
const raw_text = body.raw_text || body.rawText || null;
const drive_file_id = body.drive_file_id || body.driveFileId || null;
const source_document_name = body.source_document_name || body.sourceDocumentName || 'pasted guest list';
const source_url = body.source_url || body.sourceUrl || null;

if (!raw_text && !drive_file_id) {
  throw new Error('Need either raw_text or drive_file_id');
}

const run_id = 'guestimport_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8);

return [{ json: {
  run_id,
  source_document_name,
  source_url,
  drive_file_id,
  raw_text: raw_text || '(drive_file_id branch not implemented; provide raw_text)',
  has_raw_text: !!raw_text,
  received_at: new Date().toISOString(),
}}];

