const item = $input.first().json;
let text = item.content?.[0]?.text || item.text || JSON.stringify(item);
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let rows;
try { rows = JSON.parse(text); }
catch (e) {
  return [{ json: { ok: false, rejection_reason: 'invalid_json', raw_text: text.slice(0,2000), error: String(e) }}];
}

if (!Array.isArray(rows)) {
  return [{ json: { ok: false, rejection_reason: 'not_an_array', raw_text: text.slice(0,2000) }}];
}

const allowedTarget = new Set(['signal_noise','built','either']);
const allowedQ = new Set(['red','amber','green']);
const validChannels = new Set(['email','linkedin','twitter','warm_intro','other']);

const valid = [];
const skipped = [];
const meta = $('Validate').first().json;

for (const r of rows) {
  if (!r || typeof r !== 'object') continue;
  if (!r.name) { skipped.push({ reason: 'missing_name', row: r }); continue; }
  if (!allowedTarget.has(r.podcast_target)) r.podcast_target = 'either';
  if (r.quality_score && !allowedQ.has(r.quality_score)) r.quality_score = null;
  if (r.best_channel && !validChannels.has(r.best_channel)) r.best_channel = 'other';
  const clampScore = (v) => typeof v === 'number' ? Math.max(0, Math.min(100, Math.round(v))) : null;
  valid.push({
    name: String(r.name).slice(0,255),
    email: r.email || null,
    linkedin_url: r.linkedin_url || null,
    twitter_handle: r.twitter_handle || null,
    personal_url: r.personal_url || null,
    podcast_target: r.podcast_target,
    one_liner: r.one_liner || null,
    why_fit: r.why_fit || null,
    best_channel: r.best_channel || null,
    fit_score: clampScore(r.fit_score),
    attainability_score: clampScore(r.attainability_score),
    quality_score: r.quality_score || null,
    notes: r.notes || null,
    source: 'sheet_import',
    raw_data: {
      ingest_run_id: meta.run_id,
      source_document_name: meta.source_document_name,
      received_at: meta.received_at,
      extracted_raw: r,
    },
  });
}

return [{ json: { ok: true, rows: valid, skipped_count: skipped.length, total_extracted: rows.length, run_id: meta.run_id }}];

const incoming = $('Parse + Validate').first().json.rows || [];
const existing = $input.first().json || [];
const seenEmail = new Set();
const seenName = new Set();
for (const e of existing) {
  if (e.email) seenEmail.add(e.email.toLowerCase());
  if (e.name) seenName.add(e.name.toLowerCase().trim());
}
const fresh = incoming.filter(r => {
  if (r.email && seenEmail.has(r.email.toLowerCase())) return false;
  if (!r.email && r.name && seenName.has(r.name.toLowerCase().trim())) return false;
  return true;
});
return fresh.map(r => ({ json: r }));
